impl Solution {
    pub fn can_cross(a: Vec<u8>, m: usize, k: i64) -> bool {
        let n = a.len();
        if n == 0 {
            return true;
        }

        let mut dp = vec![false; n + 1];
        dp[0] = true;

        for i in 0..=n {
            if !dp[i] {
                continue;
            }

            for j in 1..=m {
                let next_pos = i + j;
                if next_pos <= n {
                    if a[next_pos] != b'C' {
                        dp[next_pos] = true;
                    }
                }
            }
        }

        dp[n]
    }
}

